mapper.select:
SELECT T1.id, T1.res_name, T1.res_path, T1.icon as icon, T1.RES_LEVEL, T1.ORDER_NO, T1.parent_Id, T1.res_type, T1.hidden, T1.res_mode, T1.remark, T1.res_url, T1.key_name, T1.keep_alive, T1.expand, T1.business_expand FROM LA_RESOURCES T1 WHERE T1.res_type != 0 AND T1.res_mode = #{query.mode}
AND T1.ID IN ( SELECT DISTINCT T.RESOURCE_ID FROM LA_ROLE_RESOURCES T WHERE T.AUTHORITY IN #{item} )
AND T1.RES_LEVEL = #{query.level}
AND T1.parent_keys LIKE CONCAT(#{query.parentId}, '%')
AND T1.res_name LIKE CONCAT('%', #{query.name}, '%')
ORDER BY T1.RES_LEVEL, T1.parent_id, T1.ORDER_NO

SELECT T1.id, T1.res_name, T1.parent_Id, T1.business_expand FROM LA_RESOURCES T1 inner join la_role_resources T2 on T1.id = T2.RESOURCE_ID
T1.res_mode = #{mode}
AND T1.res_type IN #{item}
ORDER BY T1.RES_LEVEL, T1.parent_Id, T1.ORDER_NO
